F(tot, "public static final int[] HALFS = new int[] { %s };" % ", ".join(str(_h) for _h in HALF))   # 0.4.13
M(tot, r"""
public static int[] posOf(String[] f) {
  if (f == null || f.length < 8 || f[7] == null || f[7].length() == 0) return null;
  int c = f[7].indexOf(';');
  if (c <= 0) return null;
  try { return new int[] { Integer.parseInt(f[7].substring(0, c)), Integer.parseInt(f[7].substring(c + 1)) }; } catch (Throwable t) { return null; }
}""")   # 0.4.13: a hand-placed pole's spot (dx, dz from the island centre) or null (a pad)
M(tot, r"""
public static int covAt(int size, int r, int dx, int dz) {
  int h = HALFS[size >= 3 ? 2 : (size == 2 ? 1 : 0)];
  long lim = (long) r * (long) r;
  int n = 0;
  for (int x = 1 - h; x < h; x++) {
    for (int z = 1 - h; z < h; z++) {
      if (x >= -1 && x <= 1 && z >= -1 && z <= 1) continue;
      long a = (long) (x - dx);
      long b = (long) (z - dz);
      if (a * a + b * b <= lim) n++;
    }
  }
  return n;
}""")   # 0.4.13: the crop cells (the cov rule: inside the rim, not the centre 3 x 3) within r of (dx, dz)
M(tot, r"""
public static int cov(int size, int r) {
  int rr = r < 0 ? 0 : (r > COV_R ? COV_R : r);
  if (size >= 3) return COV3[rr];
  if (size == 2) return COV2[rr];
  return COV1[rr];
}""")
M(tot, r"""
public static int covOf(int size, String[] f, int r) {
  int[] o = posOf(f);
  return o == null ? cov(size, r) : covAt(size, r, o[0], o[1]);
}""")
M(tot, r"""
public static double ownMult(String[] f, long t) {
  double m = 1.0 + 0.2 * (double) countMod(f, "faster") + 0.1 * (double) countMod(f, "replant") + 0.1 * (double) countMod(f, "compost");
  if (boosted(f, t)) m = m * (1.0 + (double) @PKG@.ShCfg.BOOST_PCT / 100.0);
  return m;
}""")
# a worker's items / minute on an island of `size`: min(tier speed x (crops in range / crops in the Harvest Spirit I range on a Small
# island), totem.workerMax) x its own modifiers / booster
M(tot, r"""
public static double workerRate(int kd, String[] f, int size, long t) {
  int ti = idx(f[0]);
  if (ti < 0 || !WORKER[ti] || !accepts(ti, kd)) return 0.0;   // 0.3: a worker works only in its own shards
  int ref = cov(1, @PKG@.ShCfg.RANGES[0]);
  if (ref < 1) ref = 1;
  double reach = (double) covOf(size, f, range(f, t)) / (double) ref;   // 0.4.13: around its own spot when placed by hand
  if (kd == 5) reach = 1.0;   // 0.4.11: an arena has no tiles to cover - the tier's speed (combat.cagePct / cageGrowth act on the whole island: ShTotem.islandRate)
  double base = @PKG@.ShCfg.RATES[tierOf(f[1]) - 1] * reach;
  double[] wm = @PKG@.ShCfg.WMAXS;
  int tq = tierOf(f[1]) - 1;
  double mx = @PKG@.ShCfg.WORKER_MAX;
  if (wm != null && tq >= 0 && tq < wm.length) mx = wm[tq];   // 0.4.4: the cap of this totem's tier (totem.workerMax is a per-tier list)
  if (mx > 0.0 && base > mx) base = mx;   // fix4: spec 9.2 / 9.3 ceiling before the totem's own modifiers / booster
  return base * ownMult(f, t);
}""")
M(tot, "public static double workerRate(String[] f, int size, long t) { return workerRate(@PKG@.ShKind.FARM, f, size, t); }")
# a support totem's percent (day / night ones x the share; Harvest Moon = moon.bonus at night). 0.3: bonus / smelt totems add no percent
M(tot, r"""
public static double supportPct(int kd, String[] f, long t) {
  int ti = idx(f[0]);
  if (ti < 0 || WORKER[ti] || !accepts(ti, kd)) return 0.0;
  int e = EFFECT[ti];
  if (e == 5 || e == 6) return 0.0;
  double base = e == 4 ? (double) @PKG@.ShCfg.MOON_BONUS : (double) @PKG@.ShCfg.SUPPORT[tierOf(f[1]) - 1];
  double share = 1.0;
  if (e == 2) share = 1.0 - @PKG@.ShCfg.NIGHT;
  if (e == 3 || e == 4) share = @PKG@.ShCfg.NIGHT;
  return base * share * ownMult(f, t);
}""")
M(tot, "public static double supportPct(String[] f, long t) { return supportPct(@PKG@.ShKind.FARM, f, t); }")
M(tot, r"""
public static double replantMul(int kd, java.util.Properties p, int slot) {
  String[] e = entries(kd, p, slot);
  int w = 0; int r = 0;
  for (int i = 0; i < e.length; i++) {
    String[] f = parse(e[i]);
    int ti = idx(f[0]);
    if (ti < 0 || !WORKER[ti] || !accepts(ti, kd)) continue;
    w++;
    if (countMod(f, "replant") > 0) r++;
  }
  return w <= 0 ? 1.0 : 1.0 - 0.5 * (double) r / (double) w;
}""")
