# the island's rate at time t (items / minute; no worker = 0); 0.3: x the shard's Time Compressor
M(tot, r"""
public static double islandRate(int kd, java.util.Properties p, int slot, int size, long t) {
  String[] e = entries(kd, p, slot);
  double w = 0.0;
  double s = 0.0;
  boolean man = !@PKG@.ShIsl.auto(kd, p);   // 0.4.8: before the shard's Automation a worker works on what is planted now, at shard.manualPct
  for (int i = 0; i < e.length; i++) {
    String[] f = parse(e[i]);
    double wr = workerRate(kd, f, size, t);
    if (man && wr > 0.0) wr = wr * @PKG@.ShIsl.mfac(kd, p, slot, size, range(f, t));
    w += wr;
    s += supportPct(kd, f, t);
  }
  if (w <= 0.0) return 0.0;
  if (kd == 5) return @PKG@.ShCfg.cbOut(w * (1.0 + s / 100.0) * @PKG@.ShIsl.mult(kd, p, slot, size), @PKG@.ShIsl.rank(@PKG@.ShIsl.ty(kd, p, slot))) * tcMult(kd, p);   // 0.4.11 retune: combat.cageGrowth + cagePct of the zone, then the Time Compressor (unsqueezed)
  return w * (1.0 + s / 100.0) * tcMult(kd, p) * @PKG@.ShIsl.mult(kd, p, slot, size);   // 0.4.8: x the island's 3 sub-upgrades
}""")
M(tot, "public static double islandRate(java.util.Properties p, int slot, int size, long t) { return islandRate(@PKG@.ShKind.FARM, p, slot, size, t); }")
M(tot, r"""
public static double xpPer(int kd, java.util.Properties p, int slot, int size, long t) {
  if (kd != @PKG@.ShKind.FARM) return (double) @PKG@.ShCfg.xpOf(kd);
  int[] xw = @PKG@.ShCfg.XPWS;
  if (xw == null || xw.length < 5) return (double) @PKG@.ShCfg.XP_WHEAT;
  String[] e = entries(kd, p, slot);
  double w = 0.0;
  double x = 0.0;
  int top = 1;
  for (int i = 0; i < e.length; i++) {
    String[] f = parse(e[i]);
    int tq = tierOf(f[1]);
    if (tq > top) top = tq;
    double r = workerRate(kd, f, size, t);
    if (r > 0.0) { w += r; x += r * (double) xw[tq - 1]; }
  }
  if (w <= 0.0) return (double) xw[top - 1];
  return x / w;
}""")
