# settle one island at `now` (ms): returns the items made. 0.2: the rate is split at every booster end inside (last, now); last moves on by
# exactly the time the made items took (the part-item stays); elapsed is capped at shard.maxOfflineSec; a full store stops production
# (last = now). A Harvest Moon island rolls its bonus Enchanted crops (seeded by island + clock: settling again never re-rolls). 0.3: the
# same for every shard; the other shards' rare finds (bonus totems) are rolled the same way into <kind>.i<n>.ench (seed + the kind).
M(mth, r"""
public static double xpCapOf() {
  int[] xw = @PKG@.ShCfg.XPWS;
  double mx = (double) @PKG@.ShCfg.XP_WHEAT;
  if (xw != null) for (int i = 0; i < xw.length; i++) if ((double) xw[i] > mx) mx = (double) xw[i];
  return mx;
}""")
M(mth, r"""
public static double xpAvg(int kd, java.util.Properties p, int slot, long now) {
  double cur = @PKG@.ShTotem.xpPer(kd, p, slot, size(kd, p, slot), now);
  if (kd != FK) return cur;
  long s = @PKG@.ShStore.lng(p, ik(kd, slot, "stored"), 0L);
  if (s <= 0L) return cur;
  if (@PKG@.ShStore.lng(p, ik(kd, slot, "xpn"), -1L) != s) return cur;
  double w = -1.0;
  try { w = Double.parseDouble(@PKG@.ShStore.str(p, ik(kd, slot, "xpw"))); } catch (Throwable t) { w = -1.0; }
  if (Double.isNaN(w) || w < 0.0) return cur;
  double a = w / (double) s;
  double mx = xpCapOf();
  return a > mx ? mx : a;
}""")
M(mth, r"""
public static void xpSet(int kd, java.util.Properties p, int slot, long n, double w) {
  if (kd != FK) return;
  if (n < 0L) n = 0L;
  if (n == 0L || Double.isNaN(w) || w < 0.0) w = 0.0;
  p.setProperty(ik(kd, slot, "xpn"), String.valueOf(n));
  p.setProperty(ik(kd, slot, "xpw"), String.valueOf(w));
}""")
M(mth, r"""
public static long settle(int kd, java.util.Properties p, int slot, long now) {
  if (!hasIsland(kd, p, slot)) return 0L;
  long last = @PKG@.ShStore.lng(p, ik(kd, slot, "last"), now);
  long stored = @PKG@.ShStore.lng(p, ik(kd, slot, "stored"), 0L);
  if (stored < 0L) stored = 0L;
  double xa0 = kd == FK ? xpAvg(kd, p, slot, now) : 0.0;   // 0.4.4 fix 2: the XP per item of the stock already stored
  long cap = capOf(kd, p, slot);
  if (last > now) last = now;
  long maxOff = @PKG@.ShIsl.offMs(kd, p);   // 0.4.8: shard.manualOfflineSec (2 h) until the shard's Automation, then shard.maxOfflineSec
  if (now - last > maxOff) last = now - maxOff;
  long made = 0L;
  long from = last;
  if (paused(kd, p) || stored >= cap) {   // fix (critic): a picked-up shard makes nothing until it is placed again
    last = now;
  } else {
    double acc = 0.0;
    long t = last;
    int guard = 0;
    while (t < now && guard < 64) {
      long b = @PKG@.ShTotem.nextBreak(kd, p, slot, t, now);
      acc += (double) (b - t) * rate(kd, p, slot, t) / 60000.0;
      t = b;
      guard++;
    }
    made = (long) Math.floor(acc + 0.000000001);
    if (made <= 0L) {
      made = 0L;
      if (acc <= 0.0) last = now;
    } else if (stored + made >= cap) {
      made = cap - stored; last = now;
    } else {
      double rem = (double) made;
      long u = last;
      boolean done = false;
      guard = 0;
      while (u < now && guard < 64 && !done) {
        long b = @PKG@.ShTotem.nextBreak(kd, p, slot, u, now);
        double r = rate(kd, p, slot, u);
        double seg = (double) (b - u) * r / 60000.0;
        if (r > 0.0 && rem <= seg + 0.000000001) { last = u + (long) Math.floor(rem * 60000.0 / r); done = true; }
        else { rem -= seg; u = b; }
        guard++;
      }
      if (!done) last = now;
    }
    made = @PKG@.ShIsl.consume(kd, p, slot, made, @PKG@.ShTotem.replantMul(kd, p, slot));   // 0.4.8: the planted part uses seeds (manual phase; Auto-Replant halves it)
    stored += made;
  }
  p.setProperty(ik(kd, slot, "last"), String.valueOf(last));
  p.setProperty(ik(kd, slot, "stored"), String.valueOf(stored));
  if (kd == FK) xpSet(kd, p, slot, stored, xa0 * (double) (stored - made) + (made > 0L ? (double) made * @PKG@.ShTotem.xpPer(kd, p, slot, size(kd, p, slot), from) : 0.0));   // 0.4.4 fix 2: + the new items at the tiers that made them
  if (made > 0L) {
    double c = @PKG@.ShTotem.enchChance(kd, p, slot);
    if (c > 0.0) {
      String k = p.getProperty("pkey");
      long seed = ((long) slot * 1000003L) ^ (from * 31L) ^ (k == null ? 0L : (long) k.hashCode());
      if (kd != FK) seed = seed ^ ((long) (kd + 1) * 2654435761L);   // 0.3: another shard rolls its own numbers (Farming's are 0.2's)
      java.util.Random rnd = new java.util.Random(seed);
      long hit = 0L;
      for (long i = 0L; i < made; i++) if (rnd.nextDouble() < c) hit++;
      if (hit > 0L) p.setProperty(ik(kd, slot, "ench"), String.valueOf(ench(kd, p, slot) + hit));
    }
  }
  return made;
}""")
