# any thread: load every chunk + section of the region (the engine queues it), then paint on the world thread; never hangs.
# cropsOnly = the periodic regrow (only crops on AIR, no tint / relight)
M(fill, r"""
public static java.util.concurrent.CompletableFuture paintAsync(@WLD@ w, java.util.Properties p, int kd, boolean cropsOnly) {
  java.util.concurrent.CompletableFuture done = new java.util.concurrent.CompletableFuture();
  try {
    java.util.ArrayList want;
    @PKG@.ShFill job = new @PKG@.ShFill(w, null, done);
    job.cropsOnly = cropsOnly;
    job.kind = kd;
    @PKG@.ShStore.LOCK.lock(); try {
      want = cropsOnly ? @PKG@.ShGeo.crops(p, kd) : @PKG@.ShGeo.region(p, kd);
      job.prep(p);   // 0.4.8: the seed stores + which islands the replant scan counts
    } finally { @PKG@.ShStore.LOCK.unlock(); }
    job.want = want;
    // 0.4.8: load only the chunks the region's blocks are in (16 islands reach 118 blocks out; a small shard stays small)
    java.util.HashSet seen = new java.util.HashSet();
    java.util.HashSet low = new java.util.HashSet();   // 0.4.11: chunks with a cell under y 96 (a Large combat island's cavern = section 2)
    java.util.ArrayList chl = new java.util.ArrayList();
    for (int i = 0; i < want.size(); i++) {
      int[] b = (int[]) want.get(i);
      int cx0 = b[0] >> 5; int cz0 = b[2] >> 5;
      if (seen.add(cx0 + "," + cz0)) chl.add(new int[] { cx0, cz0 });
      if (b[1] < 96) low.add(cx0 + "," + cz0);
    }
    int n = chl.size();
    job.cxs = new int[n];
    job.czs = new int[n];
    @CST@ cs = w.getChunkStore();
    java.util.ArrayList pl = new java.util.ArrayList();
    for (int i = 0; i < n; i++) {
      int[] c = (int[]) chl.get(i);
      job.cxs[i] = c[0];
      job.czs[i] = c[1];
      pl.add(cs.getChunkReferenceAsync(@CHU@.indexChunk(c[0], c[1])));
      pl.add(cs.getChunkSectionReferenceAsync(c[0], 3, c[1]));
      if (low.contains(c[0] + "," + c[1])) pl.add(cs.getChunkSectionReferenceAsync(c[0], 2, c[1]));   // 0.4.11
    }
    java.util.concurrent.CompletableFuture[] parts = new java.util.concurrent.CompletableFuture[pl.size()];
    for (int i = 0; i < parts.length; i++) parts[i] = (java.util.concurrent.CompletableFuture) pl.get(i);
    java.util.concurrent.CompletableFuture.allOf(parts).whenComplete(job);
  } catch (Throwable t) { @PKG@.ShCfg.warn("shard fill dispatch failed: " + t); done.complete(w); }
  return done;
}""")
M(fill, "public static java.util.concurrent.CompletableFuture paintAsync(@WLD@ w, java.util.Properties p, boolean cropsOnly) { return paintAsync(w, p, %d, cropsOnly); }" % FARM_K)
M(fill, r"""
public static java.util.concurrent.CompletableFuture region(@WLD@ w, java.util.Properties p, int kd) {
  return paintAsync(w, p, kd, false).orTimeout(60L, java.util.concurrent.TimeUnit.SECONDS);   // 0.4.8 fix2
}""")
