# ---- 0.4.7 the Magic Bags (SkyySacks: sacks:fn:count {UUID, id} -> Long takeable (-1 = paused), take {UUID, id, qty} -> Long removed, put
# {UUID, id, qty} -> Long returned (only what a take removed in the last 60 s - the refund path), commit {UUID, id, qty} = paid for good).
# No SkyySacks / a refusal = 0 (never throws). World thread only (the page click).
M(core, r"""
public static long bagLoose(java.util.UUID u, String id) {
  try {
    java.util.function.Function f = @PKG@.ShCfg.fn("sacks:fn:count");
    Object r = f == null ? null : f.apply(new Object[] { u, id });
    long n = r instanceof Number ? ((Number) r).longValue() : 0L;
    return n < 0L ? 0L : n;
  } catch (Throwable t) { return 0L; }
}""")
M(core, r"""
public static long bagCall(String key, java.util.UUID u, String id, long n) {
  if (n <= 0L) return 0L;
  try {
    java.util.function.Function f = @PKG@.ShCfg.fn(key);
    Object r = f == null ? null : f.apply(new Object[] { u, id, Long.valueOf(n) });
    long m = r instanceof Number ? ((Number) r).longValue() : 0L;
    return m < 0L ? 0L : m;
  } catch (Throwable t) { @PKG@.ShCfg.warnOnce("bag:" + key, "the bag bridge " + key + " failed (logged once): " + t); return 0L; }
}""")
M(core, r"""
public static long bagOpen(java.util.UUID u, String id, boolean open) {
  long n = bagLoose(u, id);
  String e = open ? encOf(id) : null;
  if (e == null || !openOn()) return n;
  return encAdd(n, bagLoose(u, e));
}""")   # 0.4.16: the Pocket's takeable count of id: loose + 100 x its Enchanted items (open = may open them; SkyySacks has takeOpen)
M(core, "public static long bagCount(java.util.UUID u, String id) { return bagOpen(u, id, true); }")   # 0.4.16: + 100 x Enchanted (was loose only)
M(core, "public static long haveAll(java.util.UUID u, @IC@[] cs, String id) { return @PKG@.ShInv.count(cs, id) + bagCount(u, id); }")
M(core, "public static long haveIn(java.util.UUID u, @IC@[] cs, String id, String[] ids) { return @PKG@.ShInv.count(cs, id) + bagOpen(u, id, opens(id, ids)); }")   # 0.4.16: one id of the cost ids
# give back what payInvBags took (inventory: the kept stacks with data exactly as they were; bags: sacks:fn:put); "" = all back, else what is LOST
M(core, r"""
public static String refundPaid(java.util.UUID u, @IC@[] cs, String[] ids, long[] inv, long[] bag, java.util.ArrayList kept) {
  String lost = "";
  for (int i = 0; i < ids.length; i++) {
    if (inv[i] > 0L) { long b = @PKG@.ShInv.giveBack(cs, ids[i], inv[i], kept); if (b < inv[i]) lost = lost + " " + (inv[i] - b) + " " + ids[i] + " (inventory)"; }
    if (bag[i] > 0L) { long b = bagCall("sacks:fn:put", u, ids[i], bag[i]); if (b < bag[i]) lost = lost + " " + (bag[i] - b) + " " + ids[i] + " (bags)"; }
  }
  if (lost.length() > 0) {
    @PKG@.ShStore.log(u + " REFUND SHORT" + lost + " - LOST, give them back with /shardadmin give or by hand");   // 0.4.12: every cost, not only tier-ups
    @PKG@.ShCfg.warn("a shard refund came back short:" + lost + " (collect.log)");
  }
  return lost;
}""")
# take ids x q: inventory first (counted, stacks with data kept), the rest from the bags; any shortfall = everything back, null.
# inv[] (returned) / bag[] = what came from where (the refund / commit amounts)
M(core, r"""
public static long[] payInvBags(java.util.UUID u, @IC@[] cs, String[] ids, long[] q, java.util.ArrayList kept, long[] bag) {
  long[] inv = new long[ids.length];
  boolean op = openOn();   // 0.4.16: SkyySacks 0.8.32+ opens Enchanted items for the Pocket part (sacks:fn:takeOpen)
  for (int i = 0; i < ids.length; i++) {
    long hi = @PKG@.ShInv.count(cs, ids[i]);
    long wi = hi < q[i] ? hi : q[i];
    inv[i] = wi > 0L ? @PKG@.ShInv.take2(cs, ids[i], wi, kept) : 0L;
    long wb = q[i] - inv[i];
    String tk = op && opens(ids[i], ids) ? "sacks:fn:takeOpen" : "sacks:fn:take";   // 0.4.16: loose first, then the fewest Enchanted opened, the change loose; all or nothing
    bag[i] = wb > 0L ? bagCall(tk, u, ids[i], wb) : 0L;
    if (inv[i] + bag[i] != q[i]) { refundPaid(u, cs, ids, inv, bag, kept); return null; }
  }
  return inv;
}""")
# 0.4.12: the raw bag answer for one id: -1 = paused (SkyySacks: no settled profile / off the world thread), else the takeable count (no
# SkyySacks / no bag home = 0); the refusal note when paused; the bag part of a payment committed (+ its collect.log words); one cost check
M(core, r"""
public static long bagHave(java.util.UUID u, String id) {
  try {
    java.util.function.Function f = @PKG@.ShCfg.fn("sacks:fn:count");
    Object r = f == null ? null : f.apply(new Object[] { u, id });
    long n = r instanceof Number ? ((Number) r).longValue() : 0L;
    return n < 0L ? -1L : n;
  } catch (Throwable t) { return 0L; }
}""")
M(core, r"""
public static String pausedTxt(java.util.UUID u, String id) {
  return bagHave(u, id) < 0L ? " - your Pocket Dimension is paused, only your inventory counts" : "";
}""")
M(core, r"""
public static String commitBags(java.util.UUID u, String[] ids, long[] bag) {
  String s = "";
  for (int i = 0; i < ids.length; i++) if (bag[i] > 0L) { bagCall("sacks:fn:commit", u, ids[i], bag[i]); s = s + " " + bag[i] + " " + ids[i]; }
  return s.length() == 0 ? "" : " (from bags:" + s + ")";
}""")
M(core, r"""
public static String needTxt(java.util.UUID u, @IC@[] cs, String[] ids, long[] q) {
  for (int i = 0; i < ids.length; i++) {
    if (q[i] <= 0L) continue;
    long have = haveIn(u, cs, ids[i], ids);   // 0.4.16: + 100 x the Pocket's Enchanted items
    if (have < q[i]) return "-You need " + @PKG@.ShCfg.num(q[i]) + " " + @PKG@.ShTotem.pretty(ids[i]) + " (you have " + @PKG@.ShCfg.num(have) + pausedTxt(u, ids[i]) + ").";
  }
  return null;
}""")
M(core, r"""
public static long sumOf(long[] a, long[] b) {
  long n = 0L;
  for (int i = 0; i < a.length; i++) n += a[i] + b[i];
  return n;
}""")
# 0.4.14 THE COMMIT of a purchase: under the lock, only when the profile file is still at the save count `ver` the decision was made at
# (else "#changed"; a busy lock = "#busy"): settled, keys = vals written, saved (a refused save = the file's reason, p undone). The
# payment happens BEFORE it with the lock released; the caller refunds on any non-null answer.
M(core, r"""
public static String commitKeys(String k, int kd, java.util.Properties p, String[] keys, String[] vals, long ver) {
  try { @PKG@.ShStore.LOCK.lock(); } catch (@PKG@.ShBusy b) { return "#busy"; }
  try {
    if (@PKG@.ShStore.ver(k) != ver) return "#changed";
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    @PKG@.ShMath.settleAll(kd, p, now());   // production up to now at the old numbers
    for (int i = 0; i < keys.length; i++) p.setProperty(keys[i], vals[i]);
    String e = @PKG@.ShStore.save(k, p);
    if (e != null) { p.clear(); p.putAll(old); }
    return e;
  } finally { @PKG@.ShStore.LOCK.unlock(); }
}""")
M(core, "public static boolean lockish(String e) { return \"#busy\".equals(e) || \"#changed\".equals(e) || \"#have\".equals(e); }")   # 0.4.14
M(core, r"""
public static String logTxt(String e) {
  if ("#busy".equals(e)) return "SHARD DATA BUSY";
  if ("#changed".equals(e)) return "CHANGED MEANWHILE";
  return "SAVE FAILED " + e;
}""")   # 0.4.14: the collect.log / totem.log word for a refused commit
M(core, r"""
public static String failTxt(String e, boolean rc, long coins) {
  String s = "#busy".equals(e) ? "-The shard is busy right now - everything is back, try again in a moment." : "-That changed meanwhile - everything is back, open it again.";
  return rc ? s : s + " Ask an admin about the " + @PKG@.ShCfg.num(coins) + " coins (collect.log).";
}""")   # 0.4.14: the click's answer when the commit met a busy lock / a changed profile (the payment went back)
# 0.3: one purchase on shard kd (0.4.14: the caller does NOT hold ShStore.LOCK - it decided at save count `ver`; commitKeys writes): `item` x qty taken first (counted), then coins (items back when they fail),
# then key = val written (a refused save undoes it and refunds both). null = bought, else the refusal line. tag / what name it in collect.log
M(core, r"""
public static String purchase(java.util.UUID u, String k, int kd, java.util.Properties p, @IC@[] cs, String item, long qty, long coins, String key, String val, String tag, String what, long ver) {
  long have = qty > 0L ? haveAll(u, cs, item) : 0L;   // 0.4.12: inventory + bags
  String nm = @PKG@.ShTotem.pretty(item);
  if (have < qty) return "-You need " + qty + " " + nm + " (you have " + have + pausedTxt(u, item) + ").";
  long purse = @PKG@.ShPay.coins(u);
  if (coins > 0L && purse >= 0L && purse < coins) return "-You need " + @PKG@.ShCfg.num(coins) + " coins (you have " + @PKG@.ShCfg.num(purse) + ").";
  java.util.ArrayList kept = new java.util.ArrayList();   // fix (critic shards03): exact refunds of stacks with data
  String[] ids = new String[] { item };
  long[] bag = new long[1];
  long[] inv = payInvBags(u, cs, ids, new long[] { qty }, kept, bag);   // 0.4.12: inventory first, then bags; all or nothing. 0.4.14: the lock released
  if (inv == null) return "-The " + nm + " could not be taken - nothing was bought.";
  long got = inv[0] + bag[0];
  if (!@PKG@.ShPay.takeCoins(u, coins)) { String lost = refundPaid(u, cs, ids, inv, bag, kept); @PKG@.ShStore.log(u + " " + k + " " + tag + " refund " + (lost.length() == 0 ? String.valueOf(got) : "SHORT" + lost) + " of " + got + " " + item); return "-The coins could not be taken - your " + nm + " is back."; }
  String e = commitKeys(k, kd, p, new String[] { key }, new String[] { val }, ver);   // 0.4.14: the record under the lock (still at ver)
  if (e != null) {   // fix (critic): not saved = undone + everything paid goes back
    String lost = refundPaid(u, cs, ids, inv, bag, kept);
    boolean rc = @PKG@.ShPay.addCoins(u, coins);
    @PKG@.ShStore.log(u + " " + k + " " + what + " " + logTxt(e) + " - refund " + (lost.length() == 0 ? String.valueOf(got) : "SHORT" + lost) + " of " + got + " " + item + ", coins " + (rc ? coins : 0L) + " of " + coins);
    if (lockish(e)) return failTxt(e, rc, coins);
    @PKG@.ShCfg.warn(tag + " not saved, refunded: " + e);
    return "-The upgrade could not be saved - your " + nm + (rc ? " and coins are" : " is") + " back." + (rc ? "" : " Ask an admin about the " + @PKG@.ShCfg.num(coins) + " coins (collect.log).");
  }
  @PKG@.ShStore.log(u + " " + k + " " + what + " paid " + coins + " coins + " + got + " " + item + commitBags(u, ids, bag) + @PKG@.ShInv.keptText(kept));   // 0.4.12: the bag part committed once saved
  return null;
}""")
# buy the next storage tier: items first (counted), then coins; items back when the coins fail (0.3: the shard's own upgrade item)
M(core, r"""
public static String buyStorage(java.util.UUID u, String k, int kd, @IC@[] cs) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  String no = gateOwn(u, k, kd, p);   // 0.4.2: the owner only
  if (no != null) return no;
  int c; long ver;
  @PKG@.ShStore.LOCK.lock(); try { c = @PKG@.ShMath.storageTier(kd, p); ver = @PKG@.ShStore.ver(k); } finally { @PKG@.ShStore.LOCK.unlock(); }   // 0.4.14: decide under the lock, pay outside it
  if (c >= 5) return "=Storage is at the highest tier.";
  int nt = c + 1;
  String r = purchase(u, k, kd, p, cs, @PKG@.ShKind.UPG[kd], (long) @PKG@.ShCfg.storeEnch(nt), @PKG@.ShCfg.storeCoins(nt), @PKG@.ShMath.kk(kd, "storage"), String.valueOf(nt), "storage", (kd == FK ? "" : @PKG@.ShKind.KEYS[kd] + " ") + "storage " + c + " -> " + nt, ver);
  if (r != null) return r;
  return "+Storage is now tier " + nt + ": " + @PKG@.ShCfg.num(@PKG@.ShMath.cap(kd, p)) + " items a new island (more with island upgrades).";
}""")
M(core, "public static String buyStorage(java.util.UUID u, String k, @IC@[] cs) { return buyStorage(u, k, FK, cs); }")
