# Pick up the totem on pad `pad`: the item with its EXACT document first (tier, modifiers, booster time left, uid), then the record;
# a refused save takes that item back by uid.
M(core, r"""
public static String pickTotem(java.util.UUID u, String k, int kd, int slot, int pad, @IC@[] cs) {
  int[] gone = null;   // 0.4.13
  Object[] o = new Object[1];
  String no = start(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  long now = now();
  String res;
  @PKG@.ShStore.LOCK.lock(); try {
    String[] f = at(kd, p, slot, pad);
    if (f == null) return "-That totem is gone - the page is up to date now.";
    if (@PKG@.ShTotem.idx(f[0]) < 0) return "-That totem's type is unknown on this server - ask an admin (totem.log).";
    if (@PKG@.ShTotem.posOf(f) != null) gone = @PKG@.ShGeo.spotOf(kd, p, slot, pad);   // 0.4.13: a hand-placed pole's block is cleared after
    @PKG@.ShMath.settle(kd, p, slot, now);
    if (f[5].length() == 0) f[5] = @PKG@.ShTotem.newUid();
    if (@PKG@.ShTotem.usable(f) && !@PKG@.ShTotem.gf(f)) f[6] = "gf";   // fix (critic shards04): it was on a pad = a pole
    @IS@ st = @PKG@.ShTotem.stack(f, now);
    if (!@PKG@.ShInv.giveStack(cs, st)) return "-Make room in your inventory first.";
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    String[] e = @PKG@.ShTotem.entries(kd, p, slot);
    String[] ne = new String[e.length - 1];
    int j = 0;
    for (int i = 0; i < e.length; i++) if (i != pad) { ne[j] = e[i]; j++; }
    @PKG@.ShTotem.setEntries(kd, p, slot, ne);
    String err = @PKG@.ShStore.save(k, p);
    if (err != null) {
      p.clear(); p.putAll(old);
      int[] w = @PKG@.ShInv.findUid(cs, st.getItemId(), f[5]);
      boolean took = w != null && @PKG@.ShInv.takeSlot(cs, w[0], w[1], st.getItemId(), f[5]);
      tlog(u + " " + k + " pickup " + @PKG@.ShTotem.fmt(f) + " SAVE FAILED " + err + " - item taken back " + took);
      return "-The totem could not be saved - nothing changed.";
    }
    tlog(u + " " + k + (kd == FK ? "" : " " + @PKG@.ShKind.KEYS[kd]) + " pickup slot " + slot + " pad " + pad + " " + @PKG@.ShTotem.fmt(f));
    res = "+" + @PKG@.ShTotem.name(f) + " is in your inventory - its tier, modifiers and booster stay with it.";
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (gone != null && @PKG@.ShWorld2.clearAt(k, kd, gone)) return res;   // 0.4.13 (the clear repaints after)
  @PKG@.ShWorld2.repaint(k, kd);
  return res;
}""")
M(core, "public static String pickTotem(java.util.UUID u, String k, int slot, int pad, @IC@[] cs) { return pickTotem(u, k, FK, slot, pad, cs); }")
# add modifier `mi` (one item taken, counted) into the first free modifier slot
M(core, r"""
public static String addMod(java.util.UUID u, String k, int kd, int slot, int pad, int mi, @IC@[] cs) {
  Object[] o = new Object[1];
  String no = start(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  if (mi < 0 || mi >= @PKG@.ShTotem.MOD_ITEMS.length) return "-You have no totem modifiers - craft them on the Craft tab.";
  String mid = @PKG@.ShTotem.MOD_ITEMS[mi];
  String e0;
  @PKG@.ShStore.LOCK.lock(); try {   // 0.4.14: decide under the lock (the entry as checked), pay outside it, record under it
    String[] f = at(kd, p, slot, pad);
    if (f == null) return "-That totem is gone - the page is up to date now.";
    if (f[2].length() != 0 && f[3].length() != 0) return "-Both modifier slots are full - remove one first.";
    e0 = @PKG@.ShTotem.fmt(f);
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (haveAll(u, cs, mid) < 1L) return "-You have no " + @PKG@.ShTotem.MOD_NAMES[mi] + " modifier" + pausedTxt(u, mid) + ".";   // 0.4.12: inventory + bags
  String[] ids = new String[] { mid };
  long[] bag = new long[1];
  java.util.ArrayList kept = new java.util.ArrayList();
  long[] inv = payInvBags(u, cs, ids, new long[] { 1L }, kept, bag);
  if (inv == null) return "-The modifier could not be taken.";
  String err = null;
  String[] f = null;
  boolean lk = false;
  try { @PKG@.ShStore.LOCK.lock(); lk = true; } catch (@PKG@.ShBusy b) { err = "#busy"; }
  if (lk) {
    try {
      f = at(kd, p, slot, pad);
      if (f == null || !@PKG@.ShTotem.fmt(f).equals(e0)) err = "#changed";
      else {
        int which = f[2].length() == 0 ? 2 : 3;
        @PKG@.ShMath.settle(kd, p, slot, now());
        java.util.Properties old = new java.util.Properties();
        old.putAll(p);
        f[which] = @PKG@.ShTotem.MOD_KEYS[mi];
        put(kd, p, slot, pad, f);
        err = @PKG@.ShStore.save(k, p);
        if (err != null) { p.clear(); p.putAll(old); }
      }
    } finally { @PKG@.ShStore.LOCK.unlock(); }
  }
  if (err != null) {
    String lost = refundPaid(u, cs, ids, inv, bag, kept);
    tlog(u + " " + k + " addmod " + mid + " " + logTxt(err) + " - back " + (lost.length() == 0 ? "1" : "SHORT" + lost));
    return lockish(err) ? failTxt(err, true, 0L) : "-Could not be saved - your modifier is back.";
  }
  tlog(u + " " + k + " addmod slot " + slot + " pad " + pad + " " + mid + " -> " + @PKG@.ShTotem.fmt(f) + commitBags(u, ids, bag));
  return "+" + @PKG@.ShTotem.MOD_NAMES[mi] + " added to " + @PKG@.ShTotem.name(f) + " (" + @PKG@.ShTotem.MOD_DESC[mi] + ").";
}""")
