# THE SEED STORE (spec 7): Give seeds = every matching seed / sapling you carry (Farming: Eternal seeds first - each makes one more cell
# Eternal, never used up), up to shard.seedStoreMax; SAVED before the items are taken (a short take puts the store back). Take back = the
# store into your inventory, saved first (what does not fit goes back into the store).
M(core, r"""
public static String seedsGive(java.util.UUID u, String k, int kd, int slot, @IC@[] cs) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  String no = gateOwn(u, k, kd, p);
  if (no != null) return no;
  if (slot < 0 || slot >= @PKG@.ShMath.SLOTS) return "-Pick an island first.";
  String msg = "";
  long gotE = 0L; long gotS = 0L;
  @PKG@.ShStore.LOCK.lock(); try {
    if (!@PKG@.ShMath.hasIsland(kd, p, slot)) return "-That island is not yours yet.";
    if (@PKG@.ShIsl.auto(kd, p)) return "=This shard is automated - it needs no seeds.";
    int t = @PKG@.ShIsl.ty(kd, p, slot);
    boolean farm = "farm".equals(@PKG@.ShIsl.STYLE[kd]);
    String es = @PKG@.ShIsl.ESEED[t];
    String sd = @PKG@.ShIsl.SEED[t];
    if (!farm && !@PKG@.ShIsl.trees(kd)) return "=This shard needs no seeds.";
    if (farm && es.length() > 0) {   // Eternal seeds: one more Eternal cell each (up to the island's farm cells)
      int sz = @PKG@.ShMath.size(kd, p, slot);
      int room = @PKG@.ShIsl.farmN(sz, @PKG@.ShIsl.sub(p, kd, slot, 0)) - @PKG@.ShIsl.eternal(kd, p, slot);
      long have = @PKG@.ShInv.count(cs, es);
      long n = have < (long) room ? have : (long) room;
      if (n > 0L) {
        int e0 = @PKG@.ShIsl.eternal(kd, p, slot);
        p.setProperty(@PKG@.ShIsl.ik(kd, slot, "eternal"), String.valueOf((long) e0 + n));
        String er = @PKG@.ShStore.save(k, p);
        if (er != null) { p.setProperty(@PKG@.ShIsl.ik(kd, slot, "eternal"), String.valueOf(e0)); return "-The seed store could not be saved - nothing was taken."; }
        gotE = @PKG@.ShInv.take(cs, es, n);
        if (gotE < n) {
          p.setProperty(@PKG@.ShIsl.ik(kd, slot, "eternal"), String.valueOf((long) e0 + gotE));
          String er2 = @PKG@.ShStore.save(k, p);
          if (er2 != null) @PKG@.ShCfg.warn("the Eternal seed count of " + k + " could not be corrected (" + er2 + ")");
        }
      }
    }
    if (sd.length() > 0 && (!farm || !sd.equals(es))) {   // plain seeds (Farming) / saplings (Foraging, Orchard) into the store
      long cur = @PKG@.ShIsl.seeds(kd, p, slot);
      long room = (long) @PKG@.ShCfg.SEED_MAX - cur;
      long have = @PKG@.ShInv.count(cs, sd);
      long n = have < room ? have : room;
      if (n > 0L) {
        p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), String.valueOf(cur + n));
        String er = @PKG@.ShStore.save(k, p);
        if (er != null) { p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), String.valueOf(cur)); return "-The seed store could not be saved - nothing was taken."; }
        gotS = @PKG@.ShInv.take(cs, sd, n);
        if (gotS < n) {
          p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), String.valueOf(cur + gotS));
          String er2 = @PKG@.ShStore.save(k, p);
          if (er2 != null) @PKG@.ShCfg.warn("the seed store of " + k + " could not be corrected (" + er2 + ")");
        }
      }
    }
    if (gotE + gotS <= 0L) return "-You carry no " + (sd.length() > 0 ? @PKG@.ShTotem.pretty(sd) : "seeds") + (farm && es.length() > 0 ? " or " + @PKG@.ShTotem.pretty(es) : "") + " for this island" + (@PKG@.ShIsl.seeds(kd, p, slot) >= (long) @PKG@.ShCfg.SEED_MAX ? " (its store is full)" : "") + ".";
    @PKG@.ShStore.log(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " seeds slot " + slot + " eternal +" + gotE + " store +" + gotS);
    msg = "+" + (gotE > 0L ? gotE + " more Eternal cells" : "") + (gotE > 0L && gotS > 0L ? " and " : "") + (gotS > 0L ? gotS + " " + @PKG@.ShTotem.pretty(sd) + " in the store (" + @PKG@.ShIsl.seeds(kd, p, slot) + " now)" : "") + " - the totems replant from them.";
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  @PKG@.ShIsl.quest(u, "shard:seeds:" + @PKG@.ShKind.KEYS[kd]);
  @PKG@.ShWorld2.repaint(k, kd);
  return msg;
}""")
M(core, r"""
public static String seedsTake(java.util.UUID u, String k, int kd, int slot, @IC@[] cs) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  String no = gateOwn(u, k, kd, p);
  if (no != null) return no;
  if (slot < 0 || slot >= @PKG@.ShMath.SLOTS) return "-Pick an island first.";
  @PKG@.ShStore.LOCK.lock(); try {
    if (!@PKG@.ShMath.hasIsland(kd, p, slot)) return "-That island is not yours yet.";
    int t = @PKG@.ShIsl.ty(kd, p, slot);
    String sd = @PKG@.ShIsl.SEED[t];
    long cur = @PKG@.ShIsl.seeds(kd, p, slot);
    if (cur <= 0L || sd.length() == 0) return "=The seed store is empty.";
    p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), "0");
    String er = @PKG@.ShStore.save(k, p);
    if (er != null) { p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), String.valueOf(cur)); return "-The seed store could not be saved - nothing moved."; }
    long g = @PKG@.ShInv.give(cs, sd, cur);
    if (g < cur) {
      p.setProperty(@PKG@.ShIsl.ik(kd, slot, "seed"), String.valueOf(cur - g));
      String er2 = @PKG@.ShStore.save(k, p);
      if (er2 != null) { @PKG@.ShCfg.warn("the seed store of " + k + " could not be saved after a short take back (" + er2 + ")"); @PKG@.ShStore.log(u + " " + k + " seeds take back " + g + " of " + cur + " - REST NOT SAVED " + er2); }
    }
    @PKG@.ShStore.log(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " seeds take back slot " + slot + " " + g + " of " + cur);
    return g <= 0L ? "-Your inventory is full - the seeds stay in the store." : "+" + g + " " + @PKG@.ShTotem.pretty(sd) + " back in your inventory" + (g < cur ? " (" + (cur - g) + " did not fit and stay in the store)." : ".");
  } finally { @PKG@.ShStore.LOCK.unlock(); }
}""")

# craft recipe ri at shard kd's bench (the 0.2-0.3 craft, gated by the bench: owner, shard owned, bench tier)
M(core, r"""
public static String craftAt(java.util.UUID u, String k, int kd, int ri, @IC@[] cs) {
  Object[] o = new Object[1];
  String no = benchStart(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  int tier;
  @PKG@.ShStore.LOCK.lock(); try { tier = benchTier(kd, p, now()); } finally { @PKG@.ShStore.LOCK.unlock(); }
  String g = benchGate(kd, tier, ri);
  if (g != null) return "-" + g;
  return craft(u, ri, cs);
}""")
# TIER UP the totem in inventory section ci, slot si at shard kd's bench (spec 9.7, question 19 / 20). uid + seen = what the page showed
# (they travel in the click itself, so a second click from the old page can never tier up twice). Order: every check, the cost items
# taken (counted; refunded on any failure), then the totem in its slot SWAPPED for the same document one tier up (same uid, modifiers,
# booster left; Totem I -> Totem Pole II; gf cleared) - read back; a slot that changed meanwhile = the cost back, nothing else moved.
M(core, r"""
public static String tierUp(java.util.UUID u, String k, int kd, int ci, int si, String uid, int seen, @IC@[] cs) {
  Object[] o = new Object[1];
  String no = benchStart(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  if (ci < 0 || ci >= cs.length || cs[ci] == null) return "-That totem is not in your inventory any more.";
  @IS@ it = cs[ci].getItemStack((short) si);
  String id = it == null || it.isEmpty() ? null : it.getItemId();
  int ti = @PKG@.ShTotem.itemIdx(id);
  if (ti < 0) return "-That totem is not in your inventory any more.";
  long now = now();
  @BD@ d = @PKG@.ShTotem.docOf(it);
  String docUid = @PKG@.ShTotem.dstr(d, "uid");
  if (!docUid.equals(uid == null ? "" : uid)) return "-That totem moved in your inventory - look again.";
  String[] f = @PKG@.ShTotem.fromDoc(d, id, now);
  if (f == null) return "-That totem's document does not match its item - ask an admin (totem.log).";
  int t = @PKG@.ShTotem.tierOf(f[1]);
  if (t != seen) return "=That totem is " + @PKG@.ShTotem.name(f) + " now - the page is up to date.";
  if (!@PKG@.ShTotem.accepts(ti, kd)) return "-The " + @PKG@.ShTotem.NAMES[ti] + " tiers up at the " + @PKG@.ShTotem.kindsOf(ti) + " Totem Bench.";
  if (t >= 5) return "=" + @PKG@.ShTotem.name(f) + " is at the highest tier.";
  if (!@PKG@.ShTotem.handHeld(f)) return "-" + @PKG@.ShTotem.name(f) + " tiers up on its own page: place it on an island (shard menu, Totems tab), then right-click it.";   // 0.4.7
  int bt;
  @PKG@.ShStore.LOCK.lock(); try { bt = benchTier(kd, p, now); } finally { @PKG@.ShStore.LOCK.unlock(); }
  int cap = @PKG@.ShCfg.benchCap(bt);
  if (t + 1 > cap) return "-Bench " + @PKG@.ShTotem.ROMAN[bt - 1] + " tiers totems up to " + @PKG@.ShTotem.LADDER[cap - 1] + " - upgrade the bench first (Bench tab).";
  String c = @PKG@.ShTotem.costAt(kd, id, d == null ? null : d.toJson());   // the cost in THIS shard's material
  if (c.startsWith("err:")) return "-The tier-up cost is broken (" + c.substring(4) + ") - ask an admin (Server Setup -> Shards -> Tier-up costs).";
  Object[] rc = recipe(c);
  if (rc == null) return "-The tier-up cost could not be read - ask an admin.";
  String[] ids = (String[]) rc[0];
  long[] q = (long[]) rc[1];
  String need = needTxt(u, cs, ids, q);   // 0.4.12: inventory + bags (paused = said)
  if (need != null) return need;
  String[] nf = new String[] { f[0], String.valueOf(t + 1), f[2], f[3], f[4], f[5].length() == 0 ? @PKG@.ShTotem.newUid() : f[5], "" };
  @IS@ ns = @PKG@.ShTotem.stack(nf, now);
  if (ns == null) return "-That totem could not be tiered up - ask an admin (totem.log).";
  java.util.ArrayList kept = new java.util.ArrayList();
  long[] bag = new long[ids.length];
  long[] took = payInvBags(u, cs, ids, q, kept, bag);   // 0.4.12: inventory first, then bags
  if (took == null) return "-The cost could not be taken - everything is back.";
  // the SAME slot, swapped in one step (ItemContainer.replaceItemStackInSlot only swaps while the slot still holds exactly `it`): no
  // free slot needed, never two totems with one uid, never none
  try { cs[ci].replaceItemStackInSlot((short) si, it, ns); } catch (Throwable x) { @PKG@.ShCfg.warnOnce("tierswap", "a totem tier-up swap failed (logged once): " + x); }
  @IS@ now2 = cs[ci].getItemStack((short) si);
  @BD@ d2 = @PKG@.ShTotem.docOf(now2);
  boolean done = now2 != null && !now2.isEmpty() && id.equals(now2.getItemId()) && nf[5].equals(@PKG@.ShTotem.dstr(d2, "uid")) && @PKG@.ShTotem.dlong(d2, "tier") == (long) (t + 1);
  if (!done) {
    String lost = refundPaid(u, cs, ids, took, bag, kept);   // 0.4.12: inventory + bags back
    tlog(u + " " + k + " tierup " + @PKG@.ShTotem.fmt(f) + " NOT SWAPPED (the slot changed) - cost back " + (lost.length() == 0 ? String.valueOf(sumOf(took, bag)) : "SHORT" + lost));
    return "-That totem moved in your inventory - your items are back.";
  }
  tlog(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " tierup " + @PKG@.ShTotem.fmt(f) + " -> " + @PKG@.ShTotem.fmt(nf) + " paid " + c + commitBags(u, ids, bag) + @PKG@.ShInv.keptText(kept));
  return "+" + @PKG@.ShTotem.name(f) + " is now " + @PKG@.ShTotem.name(nf) + ((t == 1 && @PKG@.ShTotem.HAND[ti]) ? " - place it from the shard menu (Totems tab)." : ".");
}""")
# 0.4.12: the Magic Bags helpers (bagCount, bagCall, haveAll, refundPaid, payInvBags) moved up, before purchase() - every cost pays through them
# TIER UP A PLACED TOTEM (pad `pad` of island `slot`, shard kd) from its page. seen / type / uid = what the page showed (the click carries
# them: a double click or an old page can never tier up twice). The bench's rules: owner only, this shard's totem, the cost of
# ShTotem.costAt, the bench tier's cap (bench.capN; a finished bench timer counts). Items first (inventory, then bags; counted), then the
# record re-read under the lock (it must still be exactly what was checked), settled, tier + 1 (uid kept / given, gf cleared), SAVED;
# a refusal = every item back; success = the bag part committed.
M(core, r"""
public static String tierUpPlaced0(java.util.UUID u, String k, int kd, int slot, int pad, int seen, String type, String uid, @IC@[] cs) {
  Object[] o = new Object[1];
  String no = start(u, k, kd, cs, o);
  if (no != null) return no;
  if (busy(u)) return "-Your profile is still loading - try again in a moment.";
  java.util.Properties p = (java.util.Properties) o[0];
  long now = now();
  String[] f;
  int bt;
  @PKG@.ShStore.LOCK.lock(); try { f = at(kd, p, slot, pad); bt = benchTier(kd, p, now); } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (f == null) return "-That totem is gone - the page is up to date now.";
  if (!f[0].equals(type == null ? "" : type) || !f[5].equals(uid == null ? "" : uid)) return "-That pad holds another totem now - the page is up to date.";
  String[] sh = @PKG@.ShTotem.onPad(@PKG@.ShTotem.fmt(f));
  int ti = @PKG@.ShTotem.idx(f[0]);
  if (ti < 0) return "-That totem's type is unknown on this server - ask an admin (totem.log).";
  int t = @PKG@.ShTotem.tierOf(f[1]);
  if (t != seen) return "=That totem is " + @PKG@.ShTotem.name(sh) + " now - the page is up to date.";
  if (t >= 5) return "=" + @PKG@.ShTotem.name(sh) + " is at the highest tier.";
  if (!@PKG@.ShTotem.accepts(ti, kd)) return "-The " + @PKG@.ShTotem.NAMES[ti] + " tiers up in the " + @PKG@.ShTotem.kindsOf(ti) + " Shard - pick it up and place it there.";
  int cap = @PKG@.ShCfg.benchCap(bt);
  if (t + 1 > cap) return "-Your " + @PKG@.ShKind.NAMES[kd] + " Totem Bench (Bench " + @PKG@.ShTotem.ROMAN[bt - 1] + ") lets totems tier up to " + @PKG@.ShTotem.LADDER[cap - 1] + " - upgrade the bench first.";
  String c = @PKG@.ShTotem.costAt(kd, @PKG@.ShTotem.ITEMS[ti], @PKG@.ShTotem.doc(sh, now).toJson());
  if (c.startsWith("err:")) return "-The tier-up cost is broken (" + c.substring(4) + ") - ask an admin (Server Setup -> Shards -> Tier-up costs).";
  Object[] rc = recipe(c);
  if (rc == null) return "-The tier-up cost could not be read - ask an admin.";
  String[] ids = (String[]) rc[0];
  long[] q = (long[]) rc[1];
  for (int i = 0; i < ids.length; i++) {
    long have = haveIn(u, cs, ids[i], ids);   // 0.4.16: + 100 x the Pocket's Enchanted items
    if (have < q[i]) return "-You need " + @PKG@.ShCfg.num(q[i]) + " " + @PKG@.ShTotem.pretty(ids[i]) + " (you have " + @PKG@.ShCfg.num(have) + ").";
  }
  java.util.ArrayList kept = new java.util.ArrayList();
  long[] bag = new long[ids.length];
  long[] inv = payInvBags(u, cs, ids, q, kept, bag);   // 0.4.14: paid with the lock released (SkyySacks is never called while we hold it)
  if (inv == null) return "-The cost could not be taken - everything is back.";
  String res = null;
  String[] nf = null;
  java.util.Properties old = null;
  boolean lk = false;
  try { @PKG@.ShStore.LOCK.lock(); lk = true; } catch (@PKG@.ShBusy b) { res = "-The shard is busy right now - "; }   // 0.4.14: busy = the cost back below
  if (lk) { try {
    try {
      String[] f2 = at(kd, p, slot, pad);
      if (f2 == null || !@PKG@.ShTotem.fmt(f2).equals(@PKG@.ShTotem.fmt(f))) res = "-That totem changed meanwhile - ";
      else {
        @PKG@.ShMath.settle(kd, p, slot, now);
        old = new java.util.Properties();
        old.putAll(p);
        nf = new String[] { f2[0], String.valueOf(t + 1), f2[2], f2[3], f2[4], f2[5].length() == 0 ? @PKG@.ShTotem.newUid() : f2[5], "", f2.length > 7 && f2[7] != null ? f2[7] : "" };   // 0.4.13 review: a hand-placed totem keeps its spot (8th part)
        put(kd, p, slot, pad, nf);
        String err = @PKG@.ShStore.save(k, p);
        if (err != null) {
          p.clear(); p.putAll(old);
          tlog(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " tierup slot " + slot + " pad " + pad + " " + @PKG@.ShTotem.fmt(f) + " SAVE FAILED " + err + " - cost back");
          res = "-Could not be saved - ";
        }
      }
    } catch (Throwable x) {   // never keep the items on a throw: the record as it was, then the refund below
      if (old != null) { p.clear(); p.putAll(old); }
      @PKG@.ShCfg.warn("a totem tier-up failed (" + x + ") - the cost goes back");
      res = "-Something went wrong - ";
    }
  } finally { @PKG@.ShStore.LOCK.unlock(); } }
  if (res == null) {
    String bt2 = "";
    for (int i = 0; i < ids.length; i++) if (bag[i] > 0L) { bagCall("sacks:fn:commit", u, ids[i], bag[i]); bt2 = bt2 + " " + bag[i] + " " + ids[i]; }
    tlog(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " tierup slot " + slot + " pad " + pad + " " + @PKG@.ShTotem.fmt(f) + " -> " + @PKG@.ShTotem.fmt(nf) + " paid " + c + (bt2.length() > 0 ? " (from bags:" + bt2 + ")" : "") + @PKG@.ShInv.keptText(kept));
    @PKG@.ShWorld2.repaint(k, kd);
    return "+" + @PKG@.ShTotem.name(sh) + " is now " + @PKG@.ShTotem.name(nf) + ".";
  }
  String lost = refundPaid(u, cs, ids, inv, bag, kept);
  return res + (lost.length() == 0 ? "your items are back." : "some items could not come back - ask an admin (collect.log).");
}""")
M(core, "public static String tierUpPlaced(java.util.UUID u, String k, int kd, int slot, int pad, int seen, String type, String uid, @IC@[] cs) { String r = tierUpPlaced0(u, k, kd, slot, pad, seen, type, uid, cs); @PKG@.ShSnd.ok(u, r, 2); return r; }")
# UPGRADE THE BENCH one tier (spec 9.7): the collection tier, the items (counted), the coins last (items back when they fail), then the
# timer written (a refused save undoes it and refunds both). bench.upN.sec 0 = at once. No pay-to-skip.
M(core, r"""
public static String benchUp(java.util.UUID u, String k, int kd, @IC@[] cs) {
  Object[] o = new Object[1];
  String no = benchStart(u, k, kd, cs, o);
  if (no != null) return no;
  java.util.Properties p = (java.util.Properties) o[0];
  long now = now();
  int tier; long at; int to; long ver;
  @PKG@.ShStore.LOCK.lock(); try { tier = benchTier(kd, p, now); at = benchAt(kd, p); to = benchTo(kd, p); ver = @PKG@.ShStore.ver(k); } finally { @PKG@.ShStore.LOCK.unlock(); }   // 0.4.14: + the decision's save count
  if (at > now) return "=The bench is upgrading to Bench " + @PKG@.ShTotem.ROMAN[to - 1] + " - " + secs((at - now + 999L) / 1000L) + " left.";
  if (tier >= 4) return "=This Totem Bench is fully upgraded (Bench IV).";
  int nt = tier + 1;
  int need = @PKG@.ShCfg.BENCH_NEED[nt];
  int ct = @PKG@.ShPay.collTier(u, @PKG@.ShKind.COLL[kd]);
  if (need > 0 && ct < need) return "-Bench " + @PKG@.ShTotem.ROMAN[nt - 1] + " needs " + @PKG@.ShKind.CNAME[kd] + " collection " + need + " (you: " + (ct < 0 ? "?" : String.valueOf(ct)) + ").";
  String txt = @PKG@.ShCfg.benchItems(nt, kd).trim();
  Object[] rc = txt.length() == 0 ? new Object[] { new String[0], new long[0], Long.valueOf(0L) } : recipe(txt);
  if (rc == null) return "-The bench upgrade cost setting is broken - ask an admin (Server Setup -> Shards -> Totem Bench).";
  String[] ids = (String[]) rc[0];
  long[] q = (long[]) rc[1];
  long coins = @PKG@.ShCfg.BENCH_COINS[nt];
  String need = needTxt(u, cs, ids, q);   // 0.4.12: inventory + bags (paused = said)
  if (need != null) return need;
  long purse = @PKG@.ShPay.coins(u);
  if (coins > 0L && purse >= 0L && purse < coins) return "-You need " + @PKG@.ShCfg.num(coins) + " coins (you have " + @PKG@.ShCfg.num(purse) + ").";
  java.util.ArrayList kept = new java.util.ArrayList();
  long[] bag = new long[ids.length];
  int sec = @PKG@.ShCfg.BENCH_SEC[nt];
  long[] took = payInvBags(u, cs, ids, q, kept, bag);   // 0.4.12: inventory first, then bags. 0.4.14: paid with the lock released
  if (took == null) return "-The items could not be taken - nothing was bought.";
  if (!@PKG@.ShPay.takeCoins(u, coins)) { refundPaid(u, cs, ids, took, bag, kept); return "-The coins could not be taken - your items are back."; }
  String e = null;
  boolean lk = false;
  try { @PKG@.ShStore.LOCK.lock(); lk = true; } catch (@PKG@.ShBusy b) { e = "#busy"; }   // 0.4.14: busy = everything back below
  if (lk) { try {
    if (@PKG@.ShStore.ver(k) != ver) e = "#changed";
    else {
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    p.setProperty(@PKG@.ShMath.kk(kd, "bench"), String.valueOf(sec <= 0 ? nt : tier));   // a finished earlier upgrade is folded in here
    if (sec <= 0) { p.remove(@PKG@.ShMath.kk(kd, "benchTo")); p.remove(@PKG@.ShMath.kk(kd, "benchUpAt")); }
    else { p.setProperty(@PKG@.ShMath.kk(kd, "benchTo"), String.valueOf(nt)); p.setProperty(@PKG@.ShMath.kk(kd, "benchUpAt"), String.valueOf(now + 1000L * (long) sec)); }
    e = @PKG@.ShStore.save(k, p);
    if (e != null) { p.clear(); p.putAll(old); }
    }
  } finally { @PKG@.ShStore.LOCK.unlock(); } }
  if (e != null) {
    String lost = refundPaid(u, cs, ids, took, bag, kept);   // 0.4.12: inventory + bags back
    String ri = lost.length() == 0 ? String.valueOf(sumOf(took, bag)) : "SHORT" + lost;
    boolean rcn = @PKG@.ShPay.addCoins(u, coins);
    tlog(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " bench " + tier + " -> " + nt + " " + logTxt(e) + " - refund items " + ri + ", coins " + (rcn ? coins : 0L) + " of " + coins);
    if (lockish(e)) return failTxt(e, rcn, coins);
    return "-The upgrade could not be saved - your items" + (rcn ? " and coins are" : " are") + " back." + (rcn ? "" : " Ask an admin about the " + @PKG@.ShCfg.num(coins) + " coins (collect.log).");
  }
  tlog(u + " " + k + " " + @PKG@.ShKind.KEYS[kd] + " bench " + tier + " -> " + nt + " in " + sec + " s, paid " + coins + " coins + " + txt + commitBags(u, ids, bag) + @PKG@.ShInv.keptText(kept));   // 0.4.12
  if (sec <= 0) return "+Bench " + @PKG@.ShTotem.ROMAN[nt - 1] + " is ready.";
  return "+Bench " + @PKG@.ShTotem.ROMAN[nt - 1] + " in " + secs((long) sec) + " - the bench keeps working at Bench " + @PKG@.ShTotem.ROMAN[tier - 1] + " meanwhile.";
}""")

