# ================= 0.4.6 ShLv20 part 3: the task on the player's world thread =================
M(lv, r"""
public void runIn() {
  try {
    if (this.pr == null || !this.pr.isValid()) return;
    @REF@ r = this.pr.getReference();
    if (r == null || !r.isValid()) return;
    if (@PKG@.ShAdmin.giveGate(this.u, this.pr.getUsername(), r) != null) return;   // another world now / switching profile: the next scan
    catchUp(this.u, this.k, @PKG@.ShInv.containers(r.getStore(), r), this.pr);
  } catch (Throwable t) { @PKG@.ShCfg.warnOnce("lv20run", "giving a level 20 shard failed (logged once): " + t); }
  finally { PENDING.remove(this.u); }
}""")
M(lv, r"""
public void run() {   // 0.4.15 the lock guard (an extra hold left by the body = released + WARNed once)
  int h0 = @PKG@.ShStore.LOCK.getHoldCount();
  try { runIn(); } finally { ((@PKG@.ShLock) @PKG@.ShStore.LOCK).fix("ShLv20.run", h0); }
}""")

# ================= shard:fn:give (fix2, critic shards03 2nd round): the quest bridge for "all T1 shards come from quests" =================
# Object[]{ java.util.UUID player, String shard key (mining / foraging / farming / ranching / orchard / combat) } -> String, called on that
# player's WORLD THREAD (a quest reward). "+..." = given (<kind>.crafted = 1 saved BEFORE the item, ShAdmin.giveShard); "=..." = the
# profile already HAD that shard (placed once / crafted / given - hasShard) so nothing is given (the quest may count it as done);
# "-..." = refused, nothing given (unknown shard, not online, another thread, profile switching, inventory full, file not saved).
# Unlike /shardadmin give (an admin replacing a lost shard) it never hands out a second shard of a kind.
gfn = mk("ShGiveFn", None, ("java.util.function.Function",))
F(gfn, "public static volatile java.util.function.Function PLAYER_TEST = null;")   # harness: UUID -> PlayerRef stand-in
C(gfn, "public ShGiveFn() { }")
M(gfn, r"""
public static String give(java.util.UUID u, String key, @PR@ t) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  int kd = key == null ? -1 : @PKG@.ShKind.ofKey(key.toLowerCase());
  if (kd < 0) return "-Unknown shard " + key + ". Shards: " + @PKG@.ShKind.keysList() + ".";
  if (@PKG@.ShCore.busy(u)) return "-The profile is switching - try again in a moment.";
  String k = @PKG@.ShCfg.pkey(u);
  if (@PKG@.ShCore.hasShard(k, kd)) return "=" + @PKG@.ShCore.haveShard(kd);
  if (t == null || !t.isValid()) return "-That player is not online.";
  @REF@ r = t.getReference();
  if (r == null || !r.isValid()) return "-That player is not in a world.";
  String gg = @PKG@.ShAdmin.giveGate(u, t.getUsername(), r);
  if (gg != null) return gg;
  String ge = @PKG@.ShAdmin.giveShard(k, kd, @PKG@.ShInv.containers(r.getStore(), r));
  if (ge != null) return ge;
  @PKG@.ShStore.log("bridge give " + t.getUsername() + " " + @PKG@.ShKind.SHARD[kd]);
  return "+You got your " + @PKG@.ShKind.NAMES[kd] + " Shard. Place it on your island, then right-click it.";
}""")
M(gfn, r"""
public Object applyIn(Object o) {
  try {
    if (!(o instanceof Object[])) return "-Bad call: Object[]{ UUID, String shard }.";
    Object[] a = (Object[]) o;
    if (a.length < 2 || !(a[0] instanceof java.util.UUID) || !(a[1] instanceof String)) return "-Bad call: Object[]{ UUID, String shard }.";
    java.util.UUID u = (java.util.UUID) a[0];
    @PR@ t;
    if (PLAYER_TEST != null) { Object x = PLAYER_TEST.apply(u); t = x instanceof @PR@ ? (@PR@) x : null; }
    else t = @UNI@.get().getPlayer(u);
    return give(u, (String) a[1], t);
  } catch (Throwable t) { @PKG@.ShCfg.warn("shard:fn:give failed: " + t); return "-The shard could not be given (server log)."; }
}""")
M(gfn, r"""
public Object apply(Object o) {   // 0.4.15 the lock guard (an extra hold left by the body = released + WARNed once)
  int h0 = @PKG@.ShStore.LOCK.getHoldCount();
  Object r = null;
  try { r = applyIn(o); } finally { ((@PKG@.ShLock) @PKG@.ShStore.LOCK).fix("ShGiveFn.apply", h0); }
  return r;
}""")

# ================= 0.4.8 shard:fn:door (spec 5): SkyyIslands 0.5.25 places the Skyy_Shard_<Kind> block on its starter island and calls this.
# Object[]{ UUID owner, String pkey, String kind, String world, Integer x, Integer y, Integer z } -> "+" recorded (the door is the shard's
# placed portal now) / "+kept" (recorded beside a portal the player placed on this island) / "=" already known / "-..." refused. The shard
# gets its T1 island (manual phase) if it has none. Any thread (it reads the islands bridge and writes the profile's shard file).
dfn = mk("ShDoor", None, ("java.util.function.Function",))
F(dfn, "public static final java.util.concurrent.atomic.AtomicLong DOORS = new java.util.concurrent.atomic.AtomicLong();")
C(dfn, "public ShDoor() { }")
M(dfn, r"""
public static String door(java.util.UUID owner, String pkey, String kind, String world, int x, int y, int z) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  int kd = kind == null ? -1 : @PKG@.ShKind.ofKey(kind);
  if (kd < 0) return "-Unknown shard " + kind + ".";
  if (!@PKG@.ShStore.validKey(pkey)) return "-Bad profile key.";
  if (world == null || world.length() == 0 || @PKG@.ShWorlds.isShard(world)) return "-A shard door goes on an island.";
  String io = @PKG@.ShRole.islandOwner(world);
  if (io != null && !io.equals(pkey)) return "-That island belongs to another profile.";
  java.util.Properties p = @PKG@.ShStore.get(pkey);
  if (p == null) return "-The shard file of " + pkey + " could not be read.";
  String where = world + "|" + x + "|" + y + "|" + z;
  long now = System.currentTimeMillis();
  boolean take = false;
  String placed0;
  @PKG@.ShStore.LOCK.lock(); try { placed0 = @PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "placed")); } finally { @PKG@.ShStore.LOCK.unlock(); }
  boolean stale0 = placed0.length() > 0 && @PKG@.ShRole.stale(placed0, pkey);   // 0.4.14: SkyyIslands (our caller) asked with the lock released
  @PKG@.ShStore.LOCK.lock(); try {
    String dk = @PKG@.ShMath.kk(kd, "door.starter");
    String pk = @PKG@.ShMath.kk(kd, "placed");
    String door = @PKG@.ShStore.str(p, dk);
    String placed = @PKG@.ShStore.str(p, pk);
    if (where.equals(door) && where.equals(placed) && @PKG@.ShMath.owned(kd, p)) return "=";
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    take = placed.length() == 0 || placed.equals(door) || (stale0 && placed.equals(placed0));   // 0.4.14: changed meanwhile = not stale
    @PKG@.ShMath.starter(kd, p, now);
    p.setProperty(dk, where);
    if (take) {
      @PKG@.ShMath.settleAll(kd, p, now);   // a paused (picked-up) shard made nothing meanwhile: its clocks start now
      p.remove(@PKG@.ShMath.kk(kd, "paused"));
      p.setProperty(pk, where);
    }
    String e = @PKG@.ShStore.save(pkey, p);
    if (e != null) { p.clear(); p.putAll(old); @PKG@.ShCfg.warn("the " + kind + " door of " + pkey + " was not saved: " + e); return "-The shard file could not be saved."; }
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  DOORS.incrementAndGet();
  @PKG@.ShStore.log((owner == null ? "-" : owner.toString()) + " " + pkey + " " + @PKG@.ShKind.KEYS[kd] + " starter door " + where + (take ? "" : " (a placed portal on this island is kept)"));
  return take ? "+" : "+kept";
}""")
M(dfn, r"""
public Object applyIn(Object o) {
  try {
    if (!(o instanceof Object[])) return "-Bad call: Object[]{ UUID, String pkey, String kind, String world, Integer x, y, z }.";
    Object[] a = (Object[]) o;
    if (a.length < 7 || !(a[1] instanceof String) || !(a[2] instanceof String) || !(a[3] instanceof String) || !(a[4] instanceof Number) || !(a[5] instanceof Number) || !(a[6] instanceof Number))
      return "-Bad call: Object[]{ UUID, String pkey, String kind, String world, Integer x, y, z }.";
    java.util.UUID u = a[0] instanceof java.util.UUID ? (java.util.UUID) a[0] : null;
    return door(u, (String) a[1], (String) a[2], (String) a[3], ((Number) a[4]).intValue(), ((Number) a[5]).intValue(), ((Number) a[6]).intValue());
  } catch (Throwable t) { @PKG@.ShCfg.warn("shard:fn:door failed: " + t); return "-The door could not be recorded (server log)."; }
}""")
M(dfn, r"""
public Object apply(Object o) {   // 0.4.15 the lock guard (an extra hold left by the body = released + WARNed once)
  int h0 = @PKG@.ShStore.LOCK.getHoldCount();
  Object r = null;
  try { r = applyIn(o); } finally { ((@PKG@.ShLock) @PKG@.ShStore.LOCK).fix("ShDoor.apply", h0); }
  return r;
}""")

